using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fixed: DateTime.UtcNow is non-deterministic and causes
        // "pending model changes" exception in EF Core 9.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// Cosmos DB context — fixes for EF Core 9 breaking changes
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos("AccountEndpoint=https://localhost:8081/;AccountKey=placeholder", "MyDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: EF Core 9 renamed default discriminator from "Discriminator" to "$type".
        // Preserve "Discriminator" for existing documents.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
        // Preserve old format so existing documents remain accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}
class Session { public string Id { get; set; } = null!; public string Name { get; set; } = null!; }

