using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Fixed: EF Core 9 manages its own transactions during Migrate().
    // Wrapping in an explicit transaction now throws.
    void ApplyMigrations(AppDbContext db)
    {
        db.Database.Migrate();
    }

    // Fixed: Cosmos DB provider no longer supports synchronous I/O.
    // Use async equivalents for all Cosmos DB queries.
    async Task QueryCosmosAsync(CosmosDbContext db)
    {
        var sessions = await db.Sessions.ToListAsync();
        await db.SaveChangesAsync();
    }
}

